// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        uint256 ts = bound(t, 1, type(uint48).max);

        vm.warp(ts);
        vm.deal(actor, 20 ether);

        // first call in this block: admissible, must succeed in the reference
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        // second call in the SAME block: timestamp not strictly greater than
        // pastBlockTime, so the reference must revert it
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // general rule: first call succeeds AND any same-block repeat call reverts
        assertTrue(ok1 && !ok2);
    }
}
